-- Local workspace schema version 1; not the PostgreSQL target schema.
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS projects(org TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,snapshot TEXT NOT NULL,published TEXT,PRIMARY KEY(org,id));
CREATE TABLE IF NOT EXISTS audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,org TEXT NOT NULL,project TEXT NOT NULL,revision INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS receipts(org TEXT,project TEXT,actor TEXT,command_id TEXT,digest TEXT,response TEXT,PRIMARY KEY(org,project,actor,command_id));
CREATE TABLE IF NOT EXISTS publications(org TEXT NOT NULL,project TEXT NOT NULL,revision INTEGER NOT NULL,document TEXT NOT NULL,actor TEXT NOT NULL,at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(org,project,revision));
CREATE TABLE IF NOT EXISTS timesheets(id INTEGER PRIMARY KEY AUTOINCREMENT,org TEXT NOT NULL,project TEXT NOT NULL,task INTEGER NOT NULL,resource INTEGER NOT NULL,day TEXT NOT NULL,minutes INTEGER NOT NULL,actor TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted');
PRAGMA user_version=1;
COMMIT;
